import {ContractError} from './cloud-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {cardStatuses} from './phone-cards-contract.mjs';
export function createPhoneCardEditors({api,h,mount,input,area,select}){
 async function phoneCard(id){
  const [r,options]=await Promise.all([id?api.phoneCard(id):null,api.phoneCardOptions()]),key=crypto.randomUUID(),linked=new Set(r?.accounts.map(a=>a.id)||[]);
  if(r&&([['members',r.userMemberId],['devices',r.deviceId],['stores',r.storeId]].some(([k,id])=>id&&!options[k].some(v=>v.id===id))||r.accounts.some(a=>!options.accounts.some(v=>v.id===a.id))))throw new ContractError('原关联资料未读取完整，请重新打开。');
  const choices=(rows,current,device=false)=>[['','暂不关联'],...rows.filter(v=>(device?v.status!=='retired':v.active)||v.id===current).map(v=>[v.id,(v.assetTag?v.assetTag+' · ':'')+v.name+((device?v.status==='retired':!v.active)?'（已停用）':'')])];
  mount(id?'编辑手机卡档案':'登记手机卡',`<p class="planning-rule">手机卡独立建档；使用人、实名主体与运营账号负责人分别记录。保存关联会保留历史，不会修改旧账号号码、负责人或设备借用。</p>`+input('cardCode','手机卡编号',r?.cardCode||'','required maxlength="64" '+(id?'readonly':''))+input('phoneNumber','号码',r?.phoneNumber||'','required maxlength="40" inputmode="tel"')+input('carrier','运营商',r?.carrier||'','maxlength="100"')+select('status','使用状态',r?.status||'spare',Object.entries(cardStatuses))+select('userMemberId','当前使用人',r?.userMemberId||'',choices(options.members,r?.userMemberId))+select('deviceId','当前设备',r?.deviceId||'',choices(options.devices,r?.deviceId,true))+select('storeId','所属店铺',r?.storeId||'',choices(options.stores,r?.storeId))+`<fieldset class="material-picker"><legend>关联运营账号（可多选）</legend>${options.accounts.filter(a=>a.active||linked.has(a.id)).map(a=>`<label><input type="checkbox" name="accountIds" value="${h(a.id)}" ${linked.has(a.id)?'checked':''}>${h(a.name)}${a.active?'':'（已停用）'}</label>`).join('')||'<p class="muted">暂无可关联账号。</p>'}</fieldset>`+area('planDescription','套餐说明',r?.planDescription||'',1000)+input('planExpiresOn','套餐到期日期（未确认请留空）',r?.planExpiresOn||'','type="date"')+area('notes','普通备注',r?.notes||'')+'<p class="muted">实名主体请在独立授权入口维护；普通备注不填写实名资料、费用或登录凭证。</p>'+area('reason','本次登记或变更原因（必填）'),f=>api.savePhoneCard(id,{requestKey:key,cardCode:f.get('cardCode'),phoneNumber:f.get('phoneNumber'),carrier:f.get('carrier'),status:f.get('status'),userMemberId:f.get('userMemberId')||null,deviceId:f.get('deviceId')||null,storeId:f.get('storeId')||null,accountIds:f.getAll('accountIds'),planDescription:f.get('planDescription'),planExpiresOn:f.get('planExpiresOn')||null,notes:f.get('notes'),reason:f.get('reason')},r?.version),{kind:'phone-card'},()=>api.phoneCardReceipt(key,id));
 }
 async function phoneCardIdentity(id){
  const user=await api.session();if(!hasSensitive(user,'resources')||!hasSensitive(user,'resource_identity'))throw new ContractError('实名资料需要独立授权及资源管理授权。');
  const [card,history]=await Promise.all([api.phoneCard(id),api.phoneCardIdentity(id)]),latest=history.rows[0],key=crypto.randomUUID();
  mount('手机卡实名主体',`<p>${h(card.cardCode)} · ${h(card.phoneNumber)}</p>${latest&&latest.cardSnapshot.phoneNumber!==card.phoneNumber?`<p class="save-error">最近实名版本登记时的号码为 ${h(latest.cardSnapshot.phoneNumber)}，请核对本次实际实名主体。</p>`:''}<p class="planning-rule">此处仅保存实名个人或公司名称，可为外部主体。它与使用人、账号负责人分别记录；不保存身份证号码、证件照片、密码或验证码。</p>`+input('registeredEntity','实名登记主体（未确认请留空）',latest?.registeredEntity||'','maxlength="200"')+area('reason','变更原因（必填）')+'<p class="muted">清空表示当前资料待确认，旧版本仍保留。实名记录仅授权管理员可见。</p>',f=>api.savePhoneCardIdentity(id,{requestKey:key,expectedVersion:latest?.version||0,expectedCardVersion:card.version,registeredEntity:f.get('registeredEntity').trim()||null,reason:f.get('reason')}),{kind:'phone-card'},()=>api.phoneCardReceipt(key,id,'identity'));
 }
 return {phoneCard,phoneCardIdentity};
}
